import { test, expect, Page } from '@playwright/test';

test.describe('Payment Flow - Card Details and Purchase', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('https://example.com/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should successfully enter card details and complete purchase', async () => {
    // Navigate to payment section
    const proceedToPaymentButton = page.getByRole('button', { name: /proceed to payment/i });
    await expect(proceedToPaymentButton).toBeVisible();
    await proceedToPaymentButton.click();

    // Wait for payment form to load
    await page.waitForSelector('iframe[title*="card"]', { timeout: 5000 }).catch(() => null);

    // Fill in cardholder name
    const cardholderInput = page.getByLabel(/cardholder name/i);
    await expect(cardholderInput).toBeVisible();
    await cardholderInput.fill('John Doe');

    // Fill in card number
    const cardNumberInput = page.getByLabel(/card number/i);
    await expect(cardNumberInput).toBeVisible();
    await cardNumberInput.fill('4532015112830366');

    // Fill in expiry date
    const expiryInput = page.getByLabel(/expiry|expiration date/i);
    await expect(expiryInput).toBeVisible();
    await expiryInput.fill('12/25');

    // Fill in CVV
    const cvvInput = page.getByLabel(/cvv|cvc|security code/i);
    await expect(cvvInput).toBeVisible();
    await cvvInput.fill('123');

    // Fill in billing address
    const streetInput = page.getByLabel(/street address/i);
    await expect(streetInput).toBeVisible();
    await streetInput.fill('123 Main Street');

    const cityInput = page.getByLabel(/city/i);
    await expect(cityInput).toBeVisible();
    await cityInput.fill('New York');

    const stateInput = page.getByLabel(/state|province/i);
    await expect(stateInput).toBeVisible();
    await stateInput.fill('NY');

    const zipInput = page.getByLabel(/zip|postal code/i);
    await expect(zipInput).toBeVisible();
    await zipInput.fill('10001');

    // Submit payment
    const completePaymentButton = page.getByRole('button', { name: /complete purchase|pay now|submit payment/i });
    await expect(completePaymentButton).toBeVisible();
    await completePaymentButton.click();

    // Verify payment success
    await page.waitForURL(/.*success|confirmation|thank-you.*/i, { timeout: 10000 });
